//==================================================================================
// This is an autogenerated file. DO NOT EDIT.
//
// parser_top testbench. Drives a handful of representative packets sampled
// directly from the mask file (don't-care nibbles filled with concrete random
// hex digits) and self-checks the extracted field outputs against golden
// values sliced straight out of that same stimulus, using the mask's
// "field:msb:lsb" bit-position metadata -- no semantic packet knowledge
// required. Lines whose hex pattern contains a custom token are skipped (see
// README "Tool Limitations").
//==================================================================================
`timescale 1ns/1ps
module {{ module }};

logic        clk, rst;
logic [{{ data_width - 1 }}:0] data_in;
logic        data_in_sop, data_in_eop, data_in_valid;
logic        field_ready_in;
logic        data_in_ready, field_valid_out;
{% for field in fields -%}
logic [{{ field.width - 1 }}:0] {{ field.name }}_out;
{% endfor %}

initial clk = 1'b0;
always #5 clk = ~clk;

parser_top dut (
    .clk            (clk),
    .rst            (rst),
    .data_in        (data_in),
    .data_in_sop    (data_in_sop),
    .data_in_eop    (data_in_eop),
    .data_in_valid  (data_in_valid),
    .field_ready_in (field_ready_in),
    .data_in_ready  (data_in_ready),
    .field_valid_out(field_valid_out){% if fields %},{% endif %}
    {%- for field in fields %}
    .{{ field.name }}_out ({{ field.name }}_out){% if not loop.last %},{% endif %}
    {%- endfor %}
);

// ── shared flit buffer + packet driver ────────────────────────────────────
logic [{{ data_width - 1 }}:0] flits [{{ num_pipes }}];

task automatic drive_pkt(input string tag, input int n_flits);
    automatic int i;
    $display("[%0t] -- driving packet: %s (%0d flits)", $time, tag, n_flits);
    for (i = 0; i < n_flits; i++) begin
        @(posedge clk); #1;
        data_in       = flits[i];
        data_in_valid = 1'b1;
        data_in_sop   = (i == 0) ? 1'b1 : 1'b0;
        data_in_eop   = (i == n_flits-1) ? 1'b1 : 1'b0;
    end
    @(posedge clk); #1;
    data_in_valid = 1'b0;
    data_in_sop   = 1'b0;
    data_in_eop   = 1'b0;
    data_in       = '0;
endtask
{% if fields %}
// ── golden field-value queues, sliced directly from the driven stimulus ───
{% for field in fields %}
logic [{{ field.width - 1 }}:0] {{ field.name }}_golden_q[$] = '{
    {%- for v in field_goldens[field.name] %}
    {{ field.width }}'h{{ v }}{% if not loop.last %},{% endif %}
    {%- endfor %}
};
{% endfor %}
{% endif %}
// ── scoreboard ────────────────────────────────────────────────────────────
int out_cnt = 0;
always_ff @(posedge clk) begin
    if (field_valid_out) begin
        out_cnt++;
{%- if fields %}
{%- for field in fields %}
        if ({{ field.name }}_golden_q.size() > 0) begin
            automatic logic [{{ field.width - 1 }}:0] exp_{{ field.name }} = {{ field.name }}_golden_q.pop_front();
            if ({{ field.name }}_out !== exp_{{ field.name }})
                $display("[%0t] OUTPUT#%0d  MISMATCH {{ field.name }}: got %0h, expected %0h", $time, out_cnt, {{ field.name }}_out, exp_{{ field.name }});
            else
                $display("[%0t] OUTPUT#%0d  MATCH {{ field.name }}: %0h", $time, out_cnt, {{ field.name }}_out);
        end
{%- endfor %}
{%- else %}
        $display("[%0t] OUTPUT#%0d  field_valid_out pulse (mask has no field-extraction column -- nothing to check)", $time, out_cnt);
{%- endif %}
    end
end

// ── stimulus ──────────────────────────────────────────────────────────────
initial begin
    $dumpfile("{{ module }}.vcd");
    $dumpvars(0, {{ module }});
    rst            = 1'b1;
    field_ready_in = 1'b1;
    data_in        = '0;
    data_in_sop    = 1'b0;
    data_in_eop    = 1'b0;
    data_in_valid  = 1'b0;
    repeat (4) @(posedge clk); #1;
    rst = 1'b0;
    repeat (2) @(posedge clk); #1;
{% for pkt in packets %}
    // Packet {{ loop.index }}: {{ pkt.tag }}  ({{ pkt.n_flits }} flits)
    {%- for fv in pkt.flits %}
    flits[{{ loop.index0 }}] = {{ data_width }}'h{{ fv }};
    {%- endfor %}
    drive_pkt("{{ pkt.tag }}", {{ pkt.n_flits }});
    repeat (8) @(posedge clk);
{% endfor %}
    repeat (4) @(posedge clk);
    $display("[%0t] -- Done. %0d output(s) produced. --", $time, out_cnt);
    $finish;
end

endmodule: {{ module }}
